/// 「提醒」页的文字。按语言取实现。
pub fn combat(language: AppLanguage) -> &'static dyn CombatStrings {
    match language {
        AppLanguage::En => &CombatStringsEn,
        AppLanguage::Zh => &CombatStringsZh,
        AppLanguage::Ru => &CombatStringsRu,
        AppLanguage::Ja => &CombatStringsJa,
        AppLanguage::Ko => &CombatStringsKo,
        AppLanguage::Fr => &CombatStringsFr,
        AppLanguage::De => &CombatStringsDe,
        AppLanguage::Es => &CombatStringsEs,
    }
}
